.tf-single-template,
.tf-archive-template,
.tf-archive-listing,
.page-template-tf-search {
    &__legacy {
        padding: 40px 0px;

        @media #{$max768} {
            padding: 32px 0px;
        }
    }

    &__two {
        width: 100%;

        #tf-required {
            text-align: center;
            width: 100%;
            color: $color-danger;
            display: block;
        }

        @media #{$max768} {
            padding-top: 0px;
        }

        select {
            appearance: none;
            background-position: center right;
            padding-right: 22px;
            padding-top: 4px;
            background-repeat: no-repeat;
            background-size: 20px;
        }

        select:focus {
            outline: none;
        }

        .tf-section {
            background: $color-filling-fg;
            padding: 32px;
            margin-bottom: 32px;

            @media #{$max575} {
                padding: 24px;
            }
        }

        .tf-section-title {
            margin-bottom: 32px;
            color: $color-heading;
        }

        .tf-scroll-bar {
            overflow: hidden;
            overflow-y: scroll;
            height: inherit;

            &::-webkit-scrollbar {
                width: 8px;
            }

            /* Track */
            &::-webkit-scrollbar-track {
                background: $color-brand-lite;
            }

            /* Handle */
            &::-webkit-scrollbar-thumb {
                background: $scrollbar-thumb-color;
                border-radius: 50px;
                overflow: hidden;
            }

            .tf-popup-image {
                width: calc(33.33% - 7px);
                height: fit-content;
                aspect-ratio: 1/1;
                object-fit: cover;
            }
        }

        .tf-content-wrapper {
            .tf-details {
                display: flex;
                justify-content: space-between;
                flex-direction: row;
                gap: 32px;
                align-items: start;

                @media #{$max1024} {
                    gap: 24px;
                }

                .tf-details-left {
                    width: calc(100% - 30%);
                    display: flex;
                    flex-direction: column;
                    gap: 32px;

                    @media only screen and (max-width: 1366px) {
                        width: calc(100% - 170px);
                    }

                    @media #{$max1024} {
                        width: calc(100% - 246px);
                        gap: 16px;
                    }

                    .tf-details-menu {
                        @media #{$max768} {
                            padding: 16px;
                        }

                        ul {
                            @media #{$max768} {
                                gap: 16px;
                            }
                        }
                    }
                }
            }

            .tf-archive-details {
                @media #{$max1024} {
                    position: relative;
                }

                .tf-details-left {
                    @media #{$max1024} {
                        width: 100%;
                    }
                }
            }
        }

        .tf-available-room {
            .tf-available-room-gallery {
                @media #{$max768} {
                    height: 120px;
                    max-width: none;
                }

                .tf-room-gallery:nth-child(n+2) {
                    @media #{$max768} {
                        width: 48px;
                        height: 28px;
                    }

                    svg {
                        @media #{$max768} {
                            width: 10px;
                        }
                    }
                }
            }

            .tf-available-room-content {
                @media #{$max768} {
                    width: auto;
                    display: flow-root;
                }

                .tf-available-room-content-left {
                    @media #{$max768} {
                        width: 100%;
                    }

                    .tf-card-heading-info {
                        @media #{$max768} {
                            display: flex;
                            justify-content: space-between;
                            margin-bottom: 24px;
                        }

                        @media #{$max575} {
                            flex-direction: column;
                            margin-bottom: 12px;
                        }

                        .tf-section-title-and-location {
                            @media #{$max768} {
                                margin-bottom: 0px;
                                width: calc(100% - 0px);
                            }

                            @media #{$max575} {
                                width: 100%;
                                margin-bottom: 12px;
                            }

                            h2 {
                                @media #{$max768} {
                                    margin-bottom: 6px;
                                }
                            }

                            .tf-title-location {
                                @media #{$max768} {
                                    margin: 0px;
                                }
                            }
                        }

                        .tf-mobile.tf-pricing-info {
                            display: none;

                            @media #{$max768} {
                                // display: flex;
                                width: 120px;
                                flex-direction: column;
                                align-items: end;
                            }

                            @media #{$max575} {
                                align-items: start;
                            }

                            .tf-price-from {
                                .amount {
                                    @media #{$max768} {
                                        color: $color-text;
                                        font-size: 1.25rem;
                                        font-weight: 400;
                                    }
                                }
                            }
                        }
                    }

                    ul {
                        @media #{$max768} {
                            margin-bottom: 24px;
                        }
                    }
                }

                .tf-available-room-content-right {
                    @media #{$max768} {
                        width: 100%;
                        display: flow-root;
                    }

                    .tf-card-pricing-heading {
                        @media #{$max768} {
                            display: none;
                        }
                    }

                    a {
                        @media #{$max575} {
                            width: 100%;
                            padding: 10px 16px;
                        }

                        .tf-available-room-content-left {
                            @media #{$max768} {
                                width: 100%;
                            }

                            .tf-card-heading-info {
                                @media #{$max768} {
                                    display: flex;
                                    justify-content: space-between;

                                    margin-bottom: 24px;
                                }

                                @media #{$max575} {
                                    flex-direction: column;
                                    margin-bottom: 0;
                                }

                                .tf-section-title-and-location {
                                    @media #{$max768} {
                                        margin-bottom: 0px;
                                        width: calc(100% - 124px);
                                    }

                                    @media #{$max575} {
                                        width: 100%;
                                        margin-bottom: 12px;
                                    }

                                    h2 {
                                        @media #{$max768} {
                                            margin-bottom: 6px;
                                        }
                                    }

                                    .tf-title-location {
                                        @media #{$max768} {
                                            margin: 0px;
                                        }
                                    }
                                }

                                .tf-mobile.tf-pricing-info {
                                    display: none;

                                    @media #{$max768} {
                                        display: flex;
                                        width: 120px;
                                        flex-direction: column;
                                        align-items: end;
                                    }

                                    @media #{$max575} {
                                        align-items: start;
                                        width: 100%;
                                    }

                                    .tf-price-from {
                                        .amount {
                                            @media #{$max768} {
                                                color: $color-text;
                                                font-size: 1.25rem;
                                                font-weight: 400;
                                            }
                                        }
                                    }
                                }
                            }

                            ul {
                                @media #{$max768} {
                                    margin-bottom: 24px;
                                }
                            }
                        }

                        .tf-available-room-content-right {
                            @media #{$max768} {
                                width: 100%;
                                display: flow-root;
                            }

                            .tf-card-pricing-heading {
                                @media #{$max768} {
                                    display: none;
                                }
                            }

                            a {
                                @media #{$max768} {
                                    width: 100%;
                                    padding: 10px 16px;
                                    line-height: 1;
                                }
                            }
                        }
                    }
                }
            }
        }

        .tf-modify-search-btn {
            background: $color-primary;
            padding: 8px 32px;
            color: $color-heading;
            text-align: center;
            font-size: 0.75rem;
            font-weight: 600;
            cursor: pointer;
            margin-left: 16px;
            margin-right: 16px;
            display: none;

            @media #{$max768} {
                display: block;
                margin: 0;
                margin-bottom: -16px;
            }
        }

        .tf-booking-form-wrapper {
            background: $color-filling-fg;

            .tf-booking-form {
                display: flex;
                margin: 0;

                .tf-booking-form-fields {
                    display: flex;
                    width: 78%;
                    padding: 24px;
                    padding-right: 0;

                    @media #{$max1024} {
                        width: calc(100% - 150px);
                    }

                    &>div {
                        width: 30%;
                        border-right: 1px solid $color-border-lite;
                        display: flex;
                        flex-direction: column;
                        position: relative;

                        &.tf-booking-form-guest-and-room {
                            width: 30%;
                            padding-left: 25px;
                            align-items: start;
                            border-right: none;
                            cursor: pointer;

                            @media #{$max768} {
                                width: 38%;
                            }

                            @media #{$max575} {
                                width: fit-content;
                                margin: 12px 0 8px;
                                padding-left: 0;
                            }

                            .tf-booking-form-guest-and-room-inner {
                                width: fit-content;
                                position: relative;
                            }
                        }
                    }
                }

                .tf-booking-form-checkout,
                .tf-booking-form-checkin {
                    padding-left: 25px;
                    padding-right: 25px;

                    @media only screen and (max-width: 1200px) {
                        padding-right: 28px;
                        padding-left: 28px;
                    }

                    @media #{$max1024} {
                        padding-right: 15px;
                        padding-left: 15px;
                    }

                    input {
                        position: absolute;
                        height: 100%;
                        width: 100%;
                        opacity: 0;
                    }
                }

                .tf-booking-form-checkin {
                    max-width: 146px;
                }

                .tf-booking-form-checkout {
                    max-width: 155px;
                }

                .tf-booking-date {
                    color: $color-text;
                    font-size: 1.5rem;
                    text-align: right;
                    margin-right: 5px;

                    @media #{$max1024} {
                        font-size: 1.25rem;
                    }
                }

                span.tf-booking-form-title {
                    font-size: 1rem;
                    font-weight: 600;
                    margin-bottom: 8px;
                    color: $color-text;

                    @media #{$max1024} {
                        font-size: 0.875rem;
                    }

                    @media #{$max575} {
                        display: block;
                    }
                }

                span.tf-booking-month {
                    color: $color-text;
                    font-size: 1rem;
                    display: flex;
                    flex-direction: row;
                    align-items: center;
                    text-transform: capitalize;

                    @media #{$max1024} {
                        font-size: 0.875rem;
                    }

                    svg {
                        path {
                            fill: $color-text;
                        }
                    }
                }

                .tf-booking-date-wrap {
                    display: flex;
                    gap: 6px;
                    cursor: pointer;
                }

                .tf-duration {
                    line-height: 1;
                }

                .tf_label-row {
                    span#tf-required {
                        font-size: 0.75rem;
                        color: $color-danger;
                    }
                }

                .tf-booking-guest-and-room-wrap {
                    display: flex;
                    gap: 6px;
                    margin-top: 4px;
                    text-transform: capitalize;
                }

                .tf-booking-person-count span {
                    margin-right: 12px;
                }

                .tf-cancellation-refundable-text {
                    display: flex;
                    flex-direction: column;
                }

                .tf-booking-form-submit {
                    width: 22%;

                    @media #{$max1024} {
                        width: 150px;
                    }

                    button {
                        height: 100%;
                        width: 100%;
                        @include align-items(center);
                    }
                }
            }
        }

        .tf-available-rooms-wrapper {
            background: $color-filling-fg;
            padding: 32px;
            margin-bottom: 32px;

            .tf-room-filter {
                display: none;
                margin-bottom: 16px;

                h4 {
                    font-weight: 600;
                }

                ul {
                    margin: 0;
                    padding: 0;
                    display: flex;
                    gap: 10px;
                    flex-wrap: wrap;

                    li {
                        margin: 0px;
                        padding-left: 0px;
                        font-size: 1rem;
                        font-weight: 400;
                        color: $color-text;

                        @media #{$max1024} {
                            font-size: 0.75rem;
                        }

                        label {
                            padding-left: 25px;
                            margin-left: 0px;

                            .tf-checkmark {
                                border-radius: 4px;
                                border: 1px solid $color-primary;
                                background: $color-brand-lite;
                                height: 16px;
                                width: 16px;

                                &:hover {
                                    border-color: $color-brand-dark;
                                }

                                &::after {
                                    top: 1px;
                                    left: 4px;
                                    border-color: $color-primary;
                                }
                            }
                        }

                        label input:checked~.tf-checkmark {
                            background-color: transparent !important;
                            border-color: $color-primary;
                        }
                    }
                }

                &.tf-filter-show {
                    display: block;
                }
            }

            .tf-available-rooms {
                display: flex;
                flex-direction: column;
                gap: 32px;

                .tf-room-table.hotel-room-wrap {
                    overflow: unset;

                    .tf-available-room {
                        margin-bottom: 32px;

                        &:last-child {
                            margin-bottom: 0px;
                        }
                    }
                }

                .tf-nothing-found {
                    @media #{$max575} {
                        text-align: center;
                    }
                }
            }

            .tf-available-room {
                background: $color-filling-bg;
                display: flex;

                .tf-available-room-gallery {
                    min-width: 230px;
                    max-width: 230px;
                    display: flex;
                    flex-direction: row;
                    flex-wrap: wrap;
                    gap: 10px;
                    height: fit-content;

                    .tf-room-gallery {
                        img {
                            height: 100%;
                            width: 100%;
                            object-fit: cover;
                        }

                        &:nth-child(1) {
                            width: 100%;
                            height: 270px;
                        }

                        &:nth-child(n+2) {
                            width: 110px;
                            height: 110px;
                        }

                        &.tf-popup-buttons {
                            background-size: cover;
                            background-position: center;
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            position: relative;
                            z-index: 1;
                            cursor: pointer;

                            img {
                                height: 30px;
                                width: 30px;
                            }

                            &:after {
                                position: absolute;
                                content: "";
                                height: 100%;
                                width: 100%;
                                background: $color-heading;
                                opacity: .5;
                                z-index: -1;
                            }
                        }
                    }

                    .tf-room-gallery.tf-no-room-gallery {
                        height: 390px;
                    }
                }

                .tf-available-room-contents {
                    width: calc(100% - 230px);

                    @media #{$max1024} {
                        width: 100%;
                    }

                    .tf-section-title {
                        margin-bottom: 0;
                        color: $color-heading;
                        padding: 24px 24px 0;
                    }

                    h4 {
                        margin-bottom: 16px;
                    }

                    .tf-room-info-list {
                        margin-bottom: 24px;
                    }

                    .tf-option-list {
                        margin-bottom: 24px;
                        display: flex;
                        flex-direction: column;
                        gap: 12px 5px;
                    }

                    .tf-available-room-content {
                        width: 100%;
                        padding-bottom: 0;

                        &:last-child .tf-room-options-content-inner {
                            border-bottom: none;
                        }
                    }

                    .tf-room-options-content-inner {
                        border-bottom: 1px solid $color-gray;
                        @include flexbox();
                        justify-content: space-between;
                        padding-bottom: 24px;
                        width: 100%;

                        @media #{$max1024} {
                            display: block;
                        }
                    }
                }

                .tf-available-room-content {
                    width: calc(100% - 230px);
                    display: flex;
                    flex-wrap: nowrap;
                    flex: 1;
                    justify-content: space-between;
                    padding: 24px;

                    .tf-available-room-content-left {
                        width: auto;
                        display: flex;
                        flex-direction: column;

                        @media only screen and (max-width: 1366px) {
                            width: calc(100% - 206px);
                        }

                        @media #{$max1024} {
                            width: calc(100% - 177px);
                        }

                        @media #{$max768} {
                            width: calc(100% - 100px);
                        }

                        @media #{$max575} {
                            width: 100%;
                        }

                        h3 {
                            margin-bottom: 20px;
                        }

                        h2 {
                            font-weight: 700;
                            margin-bottom: 24px;
                            font-size: 1.875rem;

                            @media #{$max1024} {
                                font-size: 1.5rem;
                            }
                        }

                        ul {
                            margin: 0;
                            padding: 0;
                            display: grid;
                            grid-template-columns: 1fr 1fr;
                            gap: 12px 16px;

                            @media #{$max768} {
                                gap: 8px 5px;
                            }

                            &:last-child {
                                margin-bottom: 0;
                            }

                            li {
                                display: flex;
                                align-items: center;

                                @media #{$max1024} {
                                    font-size: 1rem;
                                }

                                @media #{$max768} {
                                    font-size: 0.875rem;
                                }

                                i {
                                    margin-right: 8px;
                                    font-size: 1.25rem;
                                    width: 20px;

                                    @media #{$max1024} {
                                        font-size: 0.875rem;
                                    }
                                }

                                a {
                                    color: $color-primary;
                                    text-decoration: none;
                                }
                            }
                        }

                        .tf-others-benefits-title {
                            color: $color-text;
                            font-size: 1rem;
                            font-weight: 600;
                            margin-bottom: 16px;
                            margin-top: auto;
                            display: block;

                            @media #{$max1024} {
                                margin-top: 16px;
                            }
                        }
                    }

                    .tf-available-room-content-right {
                        width: auto;
                        display: flex;
                        flex-direction: column;
                        align-items: flex-end;

                        @media #{$max1024} {
                            width: 153px;
                        }

                        .tf-cancellation-refundable-text {
                            display: flex;
                            flex-direction: column;
                            align-items: flex-end;
                            gap: 8px;
                            margin-bottom: 24px;

                            span {
                                display: flex;
                                align-items: center;
                                color: $color-text;

                                svg {
                                    margin-left: 8px;
                                }
                            }

                            i {
                                font-size: 0.625rem;
                                border: 1px solid;
                                height: 14px;
                                width: 14px;
                                border-radius: 50px;
                                display: flex;
                                align-items: center;
                                justify-content: center;
                                margin-left: 6px;
                            }
                        }

                        .tf-card-pricing-heading {
                            display: flex;
                            flex-direction: column;
                            align-items: end;
                        }

                        .tf-available-room-price {
                            display: flex;
                            align-items: center;
                            flex-direction: row;
                            flex-wrap: wrap;
                            justify-content: end;
                            gap: 4px;
                            margin-bottom: 58px;

                            .tf-price {
                                color: $color-heading;
                                font-weight: 400;
                                text-align: right;

                                .amount {
                                    font-weight: 400;
                                }

                                .discount-price {
                                    color: $color-text;
                                    font-size: 1rem;
                                    display: inline-flex;
                                    gap: 2px;

                                    .amount {
                                        font-weight: normal;
                                    }
                                }

                                .sale-price {
                                    font-size: 1.5rem;
                                    display: inline-flex;
                                    align-items: center;
                                    gap: 2px;

                                    .booking-type {
                                        font-size: 1rem;
                                    }
                                }
                            }

                            ins {
                                background-color: transparent;
                            }
                        }

                        .tf-available-room-select {
                            color: $color-text;
                            font-size: 1rem;
                            display: flex;
                            width: fit-content;
                            margin-bottom: 26px;
                            gap: 8px;
                            align-items: center;
                            margin-top: auto;

                            select {
                                height: 37px;
                                width: 70px;
                                padding: 8px 20px 8px 13px;
                                background-size: 10px;
                                background-position: 80% 49%;
                                text-align: center;
                                border: 1px solid $color-border-lite;
                                cursor: pointer;
                                font-weight: 700;
                            }
                        }
                    }

                    .tf-available-room-purchase-summery {
                        font-size: 0.75rem;
                        display: flex;

                        .price-per-night {
                            margin-left: 5px;
                        }
                    }

                    .tf-deposit-content {
                        text-align: right;

                        .room-deposit-wrap {
                            margin-bottom: 10px;
                        }

                        label {
                            font-size: 0.75rem;
                        }

                        input[type=checkbox] {
                            background: $color-primary;
                            border-color: $color-primary;
                            accent-color: $color-primary;
                        }
                    }

                    .roomselectissue {
                        text-align: right;
                    }

                    a.tf_btn {
                        margin-top: auto;
                        float: right;
                    }
                }
            }

            .tf-available-room-off {
                padding: 4px 12px;
                background: $color-success;
                font-size: 0.75rem;
                font-weight: 500;
                color: $color-white;
                margin-bottom: 8px;
                width: fit-content;

                @media #{$max768} {
                    position: absolute;
                    top: 55px;
                    right: 16px;
                }
            }
        }

        .tf-available-rooms-head {
            display: flex;
            justify-content: space-between;
            margin-bottom: 32px;
            align-items: center;

            @media only screen and (max-width: 1280px) {
                margin-bottom: 16px;
            }

            @media #{$max1024} {
                margin-bottom: 24px;
            }

            @media #{$max1024} {
                margin-bottom: 16px;
                gap: 16px;
            }

            @media #{$max575} {
                display: grid;
                grid-template-columns: 1fr 1fr;
            }

            .tf-total-results {
                @media #{$max575} {
                    display: none;
                }

                &.tf-mobile-results {
                    display: none;

                    @media #{$max575} {
                        display: block;
                    }
                }
            }

            h3 {
                color: $color-heading;
                font-size: 1.5rem;
                font-weight: 600;
                flex: 1;

                @media #{$max1024} {
                    font-size: 0.875rem;
                }

                &.tf-desktop-results {
                    @media #{$max575} {
                        display: none;
                    }
                }

                &.tf-mobile-results {
                    display: none;

                    @media #{$max575} {
                        display: block;
                        grid-column: 1 / -1;
                    }
                }
            }

            h2 {
                @media only screen and (max-width: 1280px) {
                    font-size: 1rem;
                }
            }

            .tf-archive-filter-showing {
                padding: 0px;
                cursor: pointer;
                display: none;

                @media #{$max1024} {
                    display: block;
                    margin-left: 10px;
                }

                @media #{$max575} {
                    width: fit-content;
                    margin-left: auto;
                }

            }

            .tf-filter {
                padding: 0px;
                cursor: pointer;

                i {
                    font-size: 1.5rem;
                    color: $color-text;
                }
            }
        }

        .tf-details-right {
            width: 480px;

            @media #{$max1600} {
                width: 380px;
            }

            @media only screen and (max-width: 1366px) {
                width: 283px;
                padding: 32px;
            }

            @media #{$max1024} {
                width: 222px;
                padding: 16px;
            }

            &.tf-archive-right {
                background-color: $color-filling-fg;
                padding: 32px;
                width: 30%;
                margin-bottom: 56px;

                @media #{$max1024} {
                    display: none;
                    position: absolute;
                    width: 100%;
                    z-index: 99;
                    top: 200px;
                    box-shadow: rgba(0, 0, 0, 0.1) 0px 10px 50px;
                }

                @media #{$max768} {
