                            .tf_btn {
                                width: 100%;
                                border-radius: 30px;
                                padding: 16px 32px;
                                font-size: 1rem;

                                &:hover {
                                    box-shadow: $color-links-box-shadow;
                                }
                            }
                        }

                        input[type="text"],
                        textarea {
                            border: 1px solid $color-border-lite;
                            padding: 8px;
                            color: $color-text;
                            font-size: 1rem;
                            border-radius: 0px;
                        }

                        textarea {
                            width: 100%;
                        }
                    }
                }
            }

            .tf-reviews-wrapper {
                padding-bottom: 0;

                .tf-section-title {
                    color: $color-heading;
                    font-size: 1.563rem;
                    font-weight: 700;
                    line-height: 1.5;
                    margin-bottom: 16px;
                }

                p {
                    margin-bottom: 0;
                }

                .tf-review-items {

                    .tf-reviews-item {
                        padding: 24px;
                        background-color: #fff;
                        margin-bottom: 16px;

                        .tf-reviews-item-header {
                            margin-bottom: 16px;
                            @include flexbox();
                            @include justify-content(space-between);
                            gap: 32px;

                            .tf-reviews-item-header-left {
                                @include flexbox();
                                gap: 16px;

                                .tf-reviews-avater img {
                                    border-radius: 50%;
                                }

                                .tf-reviews-avater-right {
                                    @include flexbox();
                                    @include flex-direction(column);
                                    gap: 8px;

                                    .tf-reviews-name {
                                        color: $color-heading;
                                        font-size: 1.25rem;
                                        font-weight: 600;
                                        line-height: 1.5;
                                    }

                                    .tf-review-rating {
                                        div {
                                            @include flexbox();
                                            gap: 8px;
                                            color: #FFB820;
                                        }

                                        span {
                                            display: none;
                                        }
                                    }
                                }
                            }


                        }

                        .tf-reviews-text p {
                            margin: 0;
                            color: $color-text;
                            font-size: 1rem;
                            line-height: 1.5;
                        }
                    }
                }
            }

            .tf-details-right {
                .tf-room-single-booking-form-wrap {
                    @include flexbox();
                    @include flex-direction(column);
                    gap: 32px;
                    margin-bottom: 32px;
                }

                .tf-room-price {
                    color: $color-heading;
                    font-size: 1.25rem;
                    font-weight: 400;
                    line-height: 1.4;

                    .woocommerce-Price-amount {
                        font-size: 1.88rem;
                        font-weight: 400;
                        line-height: 1.3;
                    }
                }

                .tf-single-booking-box-wrapper {
                    @include flex-direction(column);
                    padding: 24px 32px 32px 32px;
                    gap: 24px;
                    border-radius: 24px;
                    background-color: #fff;
                    box-shadow: 0 16px 40px 0 rgba(238, 85, 9, 0.08);

                    .tf-single-booking-box-bottom {
                        @include flexbox();
                        @include justify-content(space-between);
                        gap: 24px;
                        width: 100%;

                        .tf-select-guests,
                        .tf-select-room {
                            width: calc(50% - 12px);
                        }
                    }

                    label {
                        color: $color-heading;
                        font-size: 1rem;
                        line-height: 1.5;
                        font-weight: 400;
                    }

                    .tf-select-date {
                        width: 100%;

                        select {
                            background-size: 13px;
                            background-position: 93% center;
                        }
                    }

                    .tf-search-field {
                        background-color: $color-filling-bg;
                        padding: 8px 10px;
                        border-radius: 32px;
                        height: 48px;
                        margin-bottom: 0;
                        border: 1px solid $color-border-lite;
                        transition: all 0.2s ease;

                        &.info-select {
                            padding: 9px 20px;
                            cursor: pointer;
                            width: 100%;

                            @media #{$max1024} {
                                padding: 0 20px;
                            }

                        }

                        &.tf_acrselection {
                            width: 100%;

                            .acr-select {
                                width: 100%;

                                .acr-dec,
                                .acr-inc,
                                .tf-archive-guest-info {
                                    background: $color-filling-bg;
                                    min-width: 32px;
                                    min-height: 32px;
                                    padding: 0;
                                    display: flex;
                                    align-items: center;
                                    justify-content: center;
                                    border: 0;
                                    border-radius: 50%;
                                }

                                input {
                                    text-align: center;
                                }
                            }
                        }

                        input,
                        .tf-checkout-date {
                            color: $color-heading;
                            background: transparent;
                            border: 0;
                            font-size: 1rem;
                            line-height: 1.5;
                            padding: 0;
                            flex: 1;

                            &::placeholder {
                                color: $color-heading;
                            }
                        }

                        svg {
                            path {
                                stroke: $color-heading;
                            }
                        }

                        .tf-room-guest {
                            color: $color-heading;
                            background: transparent;
                            border: 0;
                            font-size: 1rem;
                            line-height: 1.5;
                            padding: 0;
                            flex: 1;
                            text-align: center;
                        }
                    }

                    .tf-submit-button {
                        width: 100%;

                        .tf_btn {
                            width: 100%;
                            min-height: 72px;
                            border: 2px solid $color-links;
                            background-color: $color-links;
                            font-size: 1rem;
                            line-height: 1.5;
                            margin-top: 10px;

                            @media #{$max768} {
                                min-height: 48px;
                            }

                            &:hover {
                                box-shadow: $color-links-box-shadow;
                            }
                        }
                    }

                    .tf-select-guests {
                        position: relative;

                        .tf_acrselection {
                            cursor: pointer;
                        }

                        .tf_acrselection-wrap {
                            display: unset;
                            min-width: 302px;
                            top: 60%;
                            opacity: 0;
                            visibility: hidden;
                            transition: 0.3s;
                            border-radius: 12px;
                            background: #F8FDFD;
                            padding: 6px;
                            right: 0;
                            box-shadow: rgba(238, 85, 9, 0.09) 0px 6px 17px 6px;

                            &.tf-show {
                                visibility: visible;
                                opacity: 1;
                                top: 110%;
                                margin-top: 0;
                                display: block !important;
                            }

                            .tf_acrselection {
                                border-radius: 8px;
                                background: $color-white;
                                margin-bottom: 4px;

                                &:last-child {
                                    margin-bottom: 0;
                                }

                                .acr-label {
                                    padding: 8px 8px 8px 20px;
                                    color: $color-text;
                                    font-size: 1rem;
                                    font-weight: 600;
                                }

                                .acr-select {
                                    padding: 8px 10px;
                                    border-radius: 8px;
                                    background: $color-white;
                                }

                                .acr-dec,
                                .acr-inc {
                                    min-width: 32px;
                                    min-height: 32px;
                                    border-radius: 32px;
                                    background: #DCE5E5;
                                    backdrop-filter: blur(16px);
                                    padding: 0;
                                    border: 0;

                                    svg path {
                                        stroke: $color-links;
                                    }
                                }

                                input {
                                    background: transparent;
                                    border: 0;
                                    text-align: center;
                                    color: $color-text;
                                    font-size: 1rem;
                                    font-weight: 600;
                                    height: 32px;
                                    padding: 5px;
                                }
                            }

                        }
                    }

                    .tf-search-input.form-control {
                        width: 100%;
                        opacity: 0;
                        position: absolute;
                        margin-left: -20px;
                    }
                }
            }

            .tf-house-rules {
                .tf-house-rules-wrapper {
                    @include flexbox();
                    @include flex-wrap(wrap);
                    gap: 30px;

                    .tf-not-included-house-rules,
                    .tf-included-house-rules {
                        list-style: none;
                        @include flex(0 0 calc(50% - 15px));
                        padding-left: 30px;
                        margin: 0;
                        box-sizing: border-box;

                        @media #{$max768} {
                            @include flex(0 0 100%);
                        }

                        li {
                            margin: 16px 0;
                            position: relative;

                            h6 {
                                margin: 0 0 5px 0;
                                font-weight: 500;
                                font-size: 1.125rem;
                                color: $color-primary;
                            }

                            &::before {
                                content: '\f058';
                                font-family: 'Font Awesome 5 Free';
                                position: absolute;
                                top: 0;
                                left: -29px;
                                font-size: 1.25rem;
                                color: $color-primary;
                            }

                            &::after {
                                content: '';
                                position: absolute;
                                left: -20px;
                                top: 23px;
                                width: 2px;
                                height: 99%;
                                background: $color-primary;
                            }

                            &:first-child {
                                margin-top: 0;
                            }

                            &:last-child {
                                margin-bottom: 0;

                                &::after {
                                    display: none;
                                }
                            }
                        }
                    }

                    &.tf-house-rules-full {

                        .tf-not-included-house-rules,
                        .tf-included-house-rules {
                            @include flex(0 0 100%);
                        }
                    }

                    .tf-not-included-house-rules {
                        li {
                            h6 {
                                color: $color-error;
                            }

                            &::before {
                                content: '\f057';
                                color: $color-error;
                            }

                            &::after {
                                background: $color-error;
                            }
                        }
                    }
                }
            }

            .tf-room-options {
                @include flexbox();
                @include flex-direction(column);
                gap: 16px;

                .tf-room-option {
                    @include flexbox();
                    @include justify-content(space-between);
                    padding: 24px;
                    gap: 32px;
                    border-radius: 16px;
                    background-color: $color-filling-bg;

                    @media #{$max575} {
                        @include flex-direction(column);
                    }

                    &-right {
                        @include flexbox();
                        @include flex-direction(column);
                        @include justify-content(space-between);
                        @include align-items(flex-end);
                        @include flex(0 0 200px);
                        text-align: right;

                        @media #{$max575} {
                            @include align-items(flex-start);
                            @include flex(0 0 100%);
                            text-align: left;

                            .tf_btn {
                                width: 100%;
                            }
                        }

                        .tf_btn {
                            border: 2px solid $color-links;

                            &:hover {
                                background-color: $color-primary;
                                box-shadow: $color-links-box-shadow;
                            }
                        }
                    }

                    h3 {
                        color: $color-heading;
                        font-size: 1.563rem;
                        line-height: 1.5;
                        margin: 0 0 32px 0;
                    }

                    ul.tf-room-features {
                        list-style: none;
                        @include flexbox();
                        @include flex-wrap();
                        gap: 12px 32px;
                        padding: 0;
                        margin: 0;

                        li {
                            @include flexbox();
                            gap: 8px;
                            color: $color-text;
                            font-size: 1rem;
                            line-height: 1.5;
                            @include flex(0 0 calc(50% - 16px));
                        }
                    }

                    .tf-room-off {
                        padding: 6px 16px;
                        background: #C5FBD9;
                        font-size: 0.813rem;
                        font-weight: 600;
                        color: #126832;
                        margin-bottom: 8px;
                        margin-left: auto;
                        width: fit-content;
                        border-radius: 30px;

                        @media #{$max575} {
                            margin-left: 0;
                        }
                    }

                    .tf-room-price {
                        color: $color-heading;
                        text-align: right;
                        font-size: 1.12rem;
                        font-weight: 400;
                        line-height: 1.5;
                        margin-bottom: 24px;

                        .sale-price .amount {
                            font-size: 1.25rem;
                            font-weight: 700;
                        }
                    }
                }
            }
        }
    }
}
